(function(){
'use strict';
const MAX_SESSIONS=10;
const ROMAN=['I','II','III','IV','V','VI','VII','VIII','IX','X'];
const TARGET_MODES={
  bank:'Sulla cassa reale di ogni giorno (take profit e stop loss sulla stessa base)',
  calendar:'Composto su ogni giorno (come il foglio)',
  trading:'Composto solo sui giorni di trading',
  linear:'Lineare (stessa cifra ogni giorno)'
};
const MARKETS=['Match Odds','Over/Under 0.5','Over/Under 1.5','Over/Under 2.5','Over/Under 3.5','Goal/No Goal','Correct Score','Primo tempo','Handicap asiatico','Altro'];
const SYSTEMS=[
  {name:'EXCH O1.5 GOL 25-70',target:78.9,sample:'2.554 partite',status:'confermato',side:'Punta',min:1.70,max:0,rule:"Entrata sullo 0-0 tra 20' e 30' a quota ≥ 1,70 · uscita al primo gol oppure al 71' in perdita"},
  {name:'EXCH LAY X HT',target:57.0,sample:'7.465 partite',status:'in verifica',side:'Banca',min:0,max:2.10,rule:"Banca la X all'intervallo solo sullo 0-0 o 1-1 a quota ≤ 2,10 · tenere fino al 90'"},
  {name:'EXCH UNDER 0.5 HT',target:36.8,sample:'15.677 partite',status:'in verifica',side:'Punta',min:2.95,max:0,rule:"Pre-match: exchange ≥ 2,95 (bookmaker ≥ 2,85) · trading: se 0-0 al 25'-30' banca e chiudi in verde"},
  {name:'O0.5 HT PRE+LIVE',target:66.0,sample:'1.554 partite',status:'confermato',side:'Punta',min:1.60,max:0,rule:"Live sullo 0-0 al 15' a quota ≥ 1,60 (pre-match ≥ 1,33)"}
];
const SYSTEM_VERIFY=150;
function systemByName(n){return SYSTEMS.find(x=>x.name===n)||null}
function systemForMarket(m){let t=String(m||'').toLowerCase();if(/esito finale 1x2|match odds|\b1x2\b/.test(t))return 'EXCH LAY X HT';if(/(tempo 1|1° tempo|primo tempo)/.test(t)&&/0\.5/.test(t))return 'O0.5 HT PRE+LIVE';if(/1\.5/.test(t)&&!/tempo/.test(t))return 'EXCH O1.5 GOL 25-70';return ''}
function oddsOutsideRule(sys,odds){let q=Number(odds)||0;if(!sys||!q)return false;return (sys.min&&q<sys.min-1e-9)||(sys.max&&q>sys.max+1e-9)}
const STRATEGIES=[...SYSTEMS.map(x=>x.name),'Lay the draw','Back favorito','Lay favorito','Scalping','Over live','Under','Correct score lay','Back & lay','Altro'];
const SIDES=['Punta','Banca','Trading'];
const state={loaded:false,loading:false,locked:false,periods:[],currentUid:'',tab:'diary',editor:null,notice:'',saveTimer:null,opEditUid:'',opFilter:'all',statsBy:'strategy',statsScope:'period',importPreview:null,importGeneric:null,pendingBetflagText:'',pendingBetflagMeta:null};

function root(){return document.getElementById('exchangeBoard')}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function round2(v){return Math.round((Number(v)||0)*100)/100}
function parseAmount(v){let t=String(v==null?'':v).replace(/€/gi,'').replace(/EUR/gi,'').replace(/\s/g,'').replace(/\u00a0/g,'').trim();if(!t)return null;let neg=/^\(.*\)$/.test(t);t=t.replace(/^\(|\)$/g,'').replace('−','-');if(/^(nan|n\/a|na|--|-)$/i.test(t))return null;if(t.includes(',')&&t.includes('.')){if(t.lastIndexOf(',')>t.lastIndexOf('.'))t=t.replace(/\./g,'').replace(',','.');else t=t.replace(/,/g,'')}else t=t.replace(',','.');let n=Number(t);if(!Number.isFinite(n))return null;return neg?-n:n}
function money(v,sign=false){let n=Number(v)||0;return (sign&&n>0?'+':'')+n.toLocaleString('it-IT',{minimumFractionDigits:2,maximumFractionDigits:2})+' €'}
function pct(v,d=1){return (Number(v)||0).toLocaleString('it-IT',{minimumFractionDigits:d,maximumFractionDigits:d})+'%'}
function isoDate(d){let x=d instanceof Date?d:new Date(d);return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')}
function todayIso(){return isoDate(new Date())}
function addDays(iso,n){let p=String(iso).split('-').map(Number),d=new Date(p[0],p[1]-1,p[2]+n);return isoDate(d)}
function parseDate(s){let t=String(s||'').trim(),m;if(!t)return null;m=t.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);if(m)return validIso(+m[1],+m[2],+m[3]);m=t.match(/(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/);if(m){let y=+m[3];if(y<100)y+=2000;return validIso(y,+m[2],+m[1])}const months={gen:1,feb:2,mar:3,apr:4,mag:5,giu:6,lug:7,ago:8,set:9,ott:10,nov:11,dic:12,jan:1,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,dec:12};m=t.toLowerCase().match(/(\d{1,2})\s+([a-zà]+)\.?\s+(\d{4})/i);if(m&&months[m[2].slice(0,3)])return validIso(+m[3],months[m[2].slice(0,3)],+m[1]);return null}
function validIso(y,m,d){let x=new Date(y,m-1,d);return x.getFullYear()===y&&x.getMonth()===m-1&&x.getDate()===d?`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:null}
function dateShort(iso){let [y,m,d]=iso.split('-').map(Number);return new Date(y,m-1,d).toLocaleDateString('it-IT',{day:'2-digit',month:'2-digit'})}
function dateFull(iso){let [y,m,d]=iso.split('-').map(Number);return new Date(y,m-1,d).toLocaleDateString('it-IT',{day:'2-digit',month:'2-digit',year:'numeric'})}
function uid(prefix='op'){return prefix+'_'+Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-4)}
function current(){return state.periods.find(p=>p.uid===state.currentUid)||state.periods[0]||null}
function normalizePeriod(p){p=p||{};p.uid=String(p.uid||'');p.name=String(p.name||'Periodo');p.start=/^\d{4}-\d{2}-\d{2}$/.test(String(p.start||''))?p.start:todayIso();p.cash=Math.max(0,Number(p.cash)||0);p.targetPct=Math.max(0,Number(p.targetPct==null?5:p.targetPct)||0);p.stakePct=Math.max(.1,Number(p.stakePct==null?3:p.stakePct)||3);p.length=Math.max(1,Math.min(366,Math.round(Number(p.length)||31)));p.targetMode=TARGET_MODES[p.targetMode]?p.targetMode:'calendar';p.commission=Math.max(0,Math.min(20,Number(p.commission==null?5:p.commission)||0));p.rules=p.rules||{};p.rules.stopLossPct=Math.max(0,Number(p.rules.stopLossPct==null?p.targetPct:p.rules.stopLossPct)||0);p.rules.stopWin=p.rules.stopWin===false?false:true;p.rules.maxSessions=Math.max(0,Math.min(10,Math.round(Number(p.rules.maxSessions)||0)));p.rules.maxStakePct=Math.max(0,Number(p.rules.maxStakePct)||0);p.days=p.days&&typeof p.days==='object'&&!Array.isArray(p.days)?p.days:{};p.ops=Array.isArray(p.ops)?p.ops:[];p.ops.forEach(o=>{if(o.odds_in!=null&&o.oddsIn==null)o.oddsIn=o.odds_in;if(o.odds_out!=null&&o.oddsOut==null)o.oddsOut=o.odds_out;o.uid=o.uid||uid();o.ref=o.ref||'';o.league=o.league||''});return p}
function getDay(p,day){let d=p.days[day]||{};return {sessions:Array.isArray(d.sessions)?d.sessions.slice(0,MAX_SESSIONS):[],deposit:Number(d.deposit)||0,note:String(d.note||'')}}
function setDay(p,day,d){let s=(d.sessions||[]).slice(0,MAX_SESSIONS);while(s.length&&s[s.length-1]==null)s.pop();if(!s.some(x=>x!=null)&&!Number(d.deposit)&&!String(d.note||'').trim())delete p.days[day];else p.days[day]={sessions:s,deposit:Number(d.deposit)||0,note:String(d.note||'')}}
function contains(p,day){return day>=p.start&&day<=addDays(p.start,p.length-1)}
function freeSlot(p,day){let d=getDay(p,day),used={};d.sessions.forEach((v,i)=>{if(v!=null)used[i]=1});p.ops.forEach(o=>{if(o.day===day)used[Number(o.slot)||0]=1});for(let i=0;i<MAX_SESSIONS;i++)if(!used[i])return i;return null}
function syncSlot(p,day,slot){let d=getDay(p,day),ops=p.ops.filter(o=>o.day===day&&Number(o.slot)===Number(slot));while(d.sessions.length<=slot)d.sessions.push(null);d.sessions[slot]=ops.length?round2(ops.reduce((a,o)=>a+(Number(o.profit)||0),0)):null;setDay(p,day,d)}
function clearSlot(p,day,slot){p.ops=p.ops.filter(o=>!(o.day===day&&Number(o.slot)===Number(slot)));let d=getDay(p,day);while(d.sessions.length<=slot)d.sessions.push(null);d.sessions[slot]=null;setDay(p,day,d)}
function targets(p){let g=p.targetPct/100,out=[],k=0,today=todayIso();for(let i=0;i<p.length;i++){let day=addDays(p.start,i);if(p.targetMode==='linear'||p.targetMode==='bank'){out.push(p.cash*(1+g*(i+1)));continue}if(p.targetMode==='trading'){let d=getDay(p,day),traded=d.sessions.some(v=>v!=null);if(traded||day>=today)k++}else k=i+1;out.push(p.cash*Math.pow(1+g,k))}return out}
function rows(p){let out=[],ts=targets(p),prevTarget=p.cash,prevBank=p.cash,peak=p.cash;for(let i=0;i<p.length;i++){let day=addDays(p.start,i),d=getDay(p,day),sessions=d.sessions.filter(v=>v!=null),traded=sessions.length>0,profit=round2(sessions.reduce((a,v)=>a+(Number(v)||0),0)),target=ts[i],required;if(p.targetMode==='bank'){target=prevBank*(1+p.targetPct/100);required=prevBank*p.targetPct/100}else required=target-prevTarget;let bank=Math.max(0,prevBank+profit+d.deposit),ret=traded&&prevBank>0?profit/prevBank*100:null,stop=p.rules.stopLossPct?round2(prevBank*p.rules.stopLossPct/100):null,stopped=!!(stop!=null&&traded&&profit<=-stop),reached=traded?profit>required:null,outcome='-';if(traded)outcome=reached?'RAGGIUNTO!':stopped?'STOP LOSS':'ancora '+money(required-profit);peak=Math.max(peak,bank);out.push({day,target:round2(target),required:round2(required),profit,bank:round2(bank),stake:round2(bank*p.stakePct/100),ret,outcome,reached,margin:traded?round2(bank-target):null,sessions:sessions.length,deposit:d.deposit,note:d.note,drawdown:round2(peak-bank),stop,stopped,startBank:prevBank});prevTarget=target;prevBank=bank}return out}
function summary(p){let rs=rows(p),final=rs.length?rs[rs.length-1].bank:p.cash,deposits=rs.reduce((a,r)=>a+r.deposit,0),profit=final-p.cash-deposits,traded=rs.filter(r=>r.sessions),last=-1;rs.forEach((r,i)=>{if(r.sessions||r.deposit)last=i});let elapsed=Math.max(1,Math.min(p.length,Math.max(Math.floor((new Date()-new Date(p.start+'T00:00:00'))/86400000)+1,last+1))),proj=traded.length?round2(final+(profit/elapsed)*(p.length-elapsed)):null;return {bank:round2(final),profit:round2(profit),profitPct:p.cash?profit/p.cash*100:0,deposits:round2(deposits),positive:rs.filter(r=>r.profit>0).length,negative:rs.filter(r=>r.profit<0).length,reached:rs.filter(r=>r.reached===true).length,traded:traded.length,sessions:rs.reduce((a,r)=>a+r.sessions,0),best:traded.length?Math.max(...traded.map(r=>r.profit)):0,worst:traded.length?Math.min(...traded.map(r=>r.profit)):0,targetFinal:rs.length?rs[rs.length-1].target:p.cash,maxDrawdown:rs.length?Math.max(...rs.map(r=>r.drawdown)):0,projection:proj,stopped:rs.filter(r=>r.stopped).length}}
function statusFor(p,r){if(r.stopped)return ['stop',`STOP-LOSS raggiunto: oggi ${money(r.profit,true)}. Fermati per oggi.`];if(p.rules.maxSessions&&r.sessions>=p.rules.maxSessions)return ['stop',`Hai fatto ${r.sessions} sessioni: è il massimo impostato.`];if(p.rules.stopWin&&r.reached)return ['info','Target del giorno raggiunto: puoi chiudere la giornata in positivo.'];if(p.rules.stopLossPct&&r.sessions){let left=(r.startBank*p.rules.stopLossPct/100)+r.profit;return ['ok','Margine prima dello stop-loss: '+money(left)]}return ['ok','']}
function api(url,opt){return fetch(url,Object.assign({cache:'no-store',headers:{'Content-Type':'application/json'}},opt||{})).then(async r=>{if(r.status===401||r.status===403){state.locked=true;throw new Error('AUTH')}let j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||('HTTP '+r.status));return j})}
function load(){if(state.loading)return;state.loading=true;api('/api/exchange/periods?ts='+Date.now()).then(j=>{state.periods=(j.periods||[]).map(normalizePeriod);state.currentUid=state.currentUid||state.periods[0]?.uid||'';state.loaded=true;state.loading=false;render(true)}).catch(e=>{state.loading=false;if(e.message!=='AUTH'){state.loaded=true;state.notice='Errore caricamento';render(true)}})}
function persist(p,quiet=false){clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>{api('/api/exchange/periods/'+encodeURIComponent(p.uid),{method:'PUT',body:JSON.stringify(p)}).then(j=>{let n=normalizePeriod(j.period),i=state.periods.findIndex(x=>x.uid===n.uid);if(i>=0)state.periods[i]=n;if(!quiet){state.notice='● salvataggio automatico attivo';renderNotice()}}).catch(e=>{state.notice=e.message==='AUTH'?'Accesso admin richiesto':'Salvataggio non riuscito';renderNotice()})},220)}
function renderNotice(){let n=document.getElementById('ex-save-state');if(n)n.textContent=state.notice||'● salvataggio automatico attivo'}
function lockedHtml(){return `<div class="ex-locked"><div class="ex-xbadge">X</div><h2>Diario Exchange</h2><p>Questa sezione è privata e richiede l'accesso amministratore di EasyBet.</p></div>`}
function field(label,id,value,type='text',extra=''){return `<label class="ex-field"><span>${esc(label)}</span><input id="${id}" type="${type}" value="${esc(value??'')}" ${extra}></label>`}
function selectField(label,id,items,value){let opts=Array.isArray(items)?items.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join(''):Object.keys(items).map(k=>`<option value="${k}" ${k===value?'selected':''}>${esc(items[k])}</option>`).join('');return `<label class="ex-field"><span>${esc(label)}</span><select id="${id}">${opts}</select></label>`}
function button(label,action,cls=''){return `<button type="button" class="ex-btn ${cls}" data-ex-action="${action}">${label}</button>`}

function sidebarHtml(p){let list=state.periods.map(x=>{let s=summary(x);return `<button class="ex-period-item ${p&&x.uid===p.uid?'active':''}" data-ex-period="${esc(x.uid)}"><b>${esc(x.name)}</b><span>${dateFull(x.start)} · ${x.length} gg</span><em class="${s.profit>0?'pos':s.profit<0?'neg':''}">${money(s.bank)}</em></button>`}).join('');return `<aside class="ex-sidebar"><div class="ex-brand"><div class="ex-xbadge">X</div><div><b>DIARIO</b><strong>EXCHANGE</strong><small>EasyBet Edition</small></div></div><div class="ex-side-title">I MIEI PERIODI</div><div class="ex-period-list">${list||'<div class="ex-no-period">Nessun periodo</div>'}</div>${button('+ Nuovo periodo','new-period','primary wide')} ${p?button('Periodo successivo →','next-period','wide'):''}${button('⬆ IMPORTA CSV BETFLAG','betflag-import','primary wide ex-betflag-main')}<div class="ex-side-grid">${p?button('Modifica','edit-period'):''}${p?button('Svuota','clear-period'):''}</div>${p?button('Elimina periodo','delete-period','danger wide'):''}<div class="ex-side-grid">${p?button('Esporta CSV','export-period'):''}${button('Backup','backup')}</div>${p?button('📄 Report del periodo','print-report','wide'):''}${button('Ripristina backup…','restore-backup','wide')}<div id="ex-save-state" class="ex-save-state">${esc(state.notice||'● salvataggio automatico attivo')}</div><div class="ex-disclaimer">Uso personale. Il trading sportivo comporta rischi di perdita. Gioca solo ciò che puoi permetterti di perdere. Vietato ai minori.</div><input hidden type="file" id="ex-betflag-file-global" accept=".csv,text/csv"><input hidden type="file" id="ex-restore-file" accept="application/json,.json"></aside>`}
function headerHtml(p){let s=summary(p),rs=rows(p),idx=Math.max(0,Math.min(p.length-1,Math.floor((new Date()-new Date(p.start+'T00:00:00'))/86400000))),today=rs[idx]||rs[0],target=today?today.required:0;return `<div class="ex-main-head"><div><span class="ex-eyebrow">PERIODO ATTIVO</span><h1>${esc(p.name)}</h1><p>${dateFull(p.start)} → ${dateFull(addDays(p.start,p.length-1))} · ${esc(TARGET_MODES[p.targetMode])}</p></div><div class="ex-head-chips"><span>TP ${pct(p.targetPct,2)}</span><span>SL ${p.rules.stopLossPct?pct(p.rules.stopLossPct,2):'nessuno'}</span><span>Stake ${pct(p.stakePct,2)}</span></div></div><div class="ex-top-tiles"><div><small>Cassa attuale</small><b>${money(s.bank)}</b><span>iniziale ${money(p.cash)}</span></div><div><small>Profitto del periodo</small><b class="${s.profit>0?'pos':s.profit<0?'neg':''}">${money(s.profit,true)}</b><span>${pct(s.profitPct,2)}</span></div><div><small>Target di oggi</small><b>${money(target)}</b><span>${today?today.outcome:'—'}</span></div><div><small>Giornate a target</small><b>${s.reached}</b><span>su ${s.traded} con trading</span></div><div><small>Importo da usare</small><b>${money(today?today.stake:p.cash*p.stakePct/100)}</b><span>${pct(p.stakePct,2)} cassa</span></div></div>`}
function tabsHtml(){let tabs=[['diary','Diario'],['ops','Operazioni'],['stats','Statistiche'],['chart','Andamento e riepilogo'],['systems','Verifica sistemi'],['calc','Calcolatori exchange']];return `<nav class="ex-tabs">${tabs.map(t=>`<button class="${state.tab===t[0]?'active':''}" data-ex-tab="${t[0]}">${t[1]}</button>`).join('')}</nav>`}

function quickBanner(p,day){if(!contains(p,day))return '';let r=rows(p)[Math.max(0,(new Date(day)-new Date(p.start))/86400000)],st=statusFor(p,r);if(!st[1])return '';return `<div class="ex-banner ${st[0]}">${esc(st[1])}</div>`}
function diaryHtml(p){let rs=rows(p),today=todayIso();return `<section class="ex-tab-pane"><div class="ex-quick"><b>REGISTRA UNA SESSIONE</b>${field('Giorno','ex-q-date',contains(p,today)?today:p.start,'date')} ${field('Profitto / perdita','ex-q-amount','','text','placeholder="es. 2,40 oppure -1,10"')} ${button('Aggiungi','quick-add','primary')}<span id="ex-q-msg"></span></div><div id="ex-day-banner">${quickBanner(p,contains(p,today)?today:p.start)}</div><div class="ex-table-wrap"><table class="ex-table ex-diary-table"><thead><tr><th>DATA</th><th>CASSA TARGET</th><th>PROFITTO RICH.</th><th>PROFITTO FATTO</th><th>CASSA</th><th>IMPORTO</th><th>REND. %</th><th>ESITO</th><th>MARGINE</th><th>N.</th>${ROMAN.map(x=>`<th>${x}</th>`).join('')}<th>DEP./PREL.</th><th>NOTE</th></tr></thead><tbody>${rs.map(r=>{let d=getDay(p,r.day);return `<tr class="${r.day===today?'today':''} ${r.stopped?'stoprow':''}"><td><b>${dateShort(r.day)}</b><small>${new Date(r.day+'T12:00:00').toLocaleDateString('it-IT',{weekday:'short'})}</small></td><td>${money(r.target)}</td><td>${money(r.required)}</td><td class="ex-signed-amount ${r.profit>0?'pos':r.profit<0?'neg':''}">${money(r.profit,true)}</td><td><b>${money(r.bank)}</b></td><td>${money(r.stake)}</td><td class="${r.ret>0?'pos':r.ret<0?'neg':''}">${r.ret==null?'':pct(r.ret,2)}</td><td class="ex-outcome ${r.reached?'is-reached':r.stopped?'is-stop':''}"><span>${esc(r.outcome)}</span></td><td class="ex-signed-amount ${r.margin>0?'pos':r.margin<0?'neg':''}">${r.margin==null?'':money(r.margin,true)}</td><td>${r.sessions}</td>${ROMAN.map((_,i)=>{let sv=d.sessions[i];return `<td><input class="ex-cell moneycell ${sv>0?'pos-input':sv<0?'neg-input':''}" data-ex-session="${r.day}|${i}" value="${sv==null?'':String(sv).replace('.',',')}"></td>`}).join('')}<td><input class="ex-cell moneycell ${d.deposit>0?'pos-input':d.deposit<0?'neg-input':''}" data-ex-deposit="${r.day}" value="${d.deposit?String(d.deposit).replace('.',','):''}"></td><td><input class="ex-cell note" data-ex-note="${r.day}" value="${esc(d.note)}"></td></tr>`}).join('')}</tbody></table></div><p class="ex-hint">Scrivi direttamente nelle colonne I…X il risultato di ogni sessione (virgola o punto; negativo per le perdite). In DEP./PREL. inserisci depositi positivi e prelievi negativi.</p></section>`}

function opFormHtml(p){let o=p.ops.find(x=>x.uid===state.opEditUid)||null,day=o?.day||todayIso();if(!contains(p,day))day=p.start;let slot=o?Number(o.slot):-1;let optSlots='<option value="-1">prima libera</option>'+ROMAN.map((r,i)=>`<option value="${i}" ${slot===i?'selected':''}>sessione ${r}</option>`).join('');let markets=[...new Set(MARKETS.concat(p.ops.map(x=>x.market).filter(Boolean)))],strategies=[...new Set(STRATEGIES.concat(p.ops.map(x=>x.strategy).filter(Boolean)))];return `<div class="ex-op-card"><div class="ex-op-title">${o?'MODIFICA OPERAZIONE':'NUOVA OPERAZIONE'}</div><div class="ex-op-grid">${field('Giorno','ex-op-day',day,'date')}<label class="ex-field"><span>Sessione</span><select id="ex-op-slot">${optSlots}</select></label>${field('Partita','ex-op-event',o?.event||'','text','placeholder="es. Inter - Milan"')}${selectField('Mercato','ex-op-market',markets,o?.market||MARKETS[0])}${selectField('Strategia','ex-op-strategy',strategies,o?.strategy||STRATEGIES[0])}${selectField('Punta / banca','ex-op-side',SIDES,o?.side||'Trading')}${field('Quota entrata','ex-op-odds-in',o?.oddsIn||'','number','step="0.01" min="0"')}${field('Quota uscita','ex-op-odds-out',o?.oddsOut||'','number','step="0.01" min="0"')}${field('Stake','ex-op-stake',o?.stake||'','number','step="0.01" min="0"')}${field('Minuti','ex-op-minute',o?.minute||'','text','placeholder="es. 15\'-60\'"')}${field('Profitto netto','ex-op-profit',o?.profit??'','text','placeholder="es. 2,40 o -1,10"')}${field('Note','ex-op-note',o?.note||'')}</div><div class="ex-op-actions">${button('Calcola profitto dalle quote','calc-op-profit')}<span id="ex-op-warn"></span>${o?button('Annulla modifica','cancel-op'):''}${button(o?'Salva modifiche':'Registra operazione','save-op','primary')}</div></div>`}
function opsHtml(p){let ops=[...p.ops].sort((a,b)=>(a.day+a.slot).localeCompare(b.day+b.slot));let fday=document.getElementById('ex-op-day')?.value||todayIso();if(state.opFilter==='day')ops=ops.filter(o=>o.day===fday);return `<section class="ex-tab-pane">${opFormHtml(p)}<div class="ex-ops-toolbar"><label>Mostra <select id="ex-op-filter"><option value="all" ${state.opFilter==='all'?'selected':''}>tutte le operazioni del periodo</option><option value="day" ${state.opFilter==='day'?'selected':''}>solo il giorno scelto sopra</option></select></label><div class="spacer"></div><label class="ex-file-btn primary">Importa CSV Betflag…<input hidden type="file" id="ex-betflag-file" accept=".csv,text/csv"></label><button class="ex-btn" data-ex-action="generic-import">Altra tabella / CSV…</button></div><div class="ex-table-wrap"><table class="ex-table ex-ops-table"><thead><tr><th>GIORNO</th><th>SESS.</th><th>PARTITA</th><th>CAMPIONATO</th><th>MERCATO</th><th>STRATEGIA</th><th>TIPO</th><th>Q. IN</th><th>Q. OUT</th><th>STAKE</th><th>MIN.</th><th>PROFITTO</th><th>NOTE</th><th></th></tr></thead><tbody>${ops.length?ops.slice().reverse().map(o=>`<tr><td>${dateShort(o.day)}</td><td>${ROMAN[Number(o.slot)||0]}</td><td><b>${esc(o.event)}</b></td><td>${esc(o.league)}</td><td>${esc(o.market)}</td><td>${esc(o.strategy)}</td><td><span class="ex-side ${String(o.side).toLowerCase()}">${esc(o.side)}</span></td><td>${o.oddsIn?Number(o.oddsIn).toFixed(2):''}</td><td>${o.oddsOut?Number(o.oddsOut).toFixed(2):''}</td><td>${o.stake?money(o.stake):''}</td><td>${esc(o.minute||'')}</td><td class="${o.profit>0?'pos':o.profit<0?'neg':''}"><b>${money(o.profit,true)}</b></td><td>${esc(o.note||'')}</td><td><button class="ex-row-btn" data-ex-action="edit-op" data-op="${o.uid}">✎</button><button class="ex-row-btn danger" data-ex-action="delete-op" data-op="${o.uid}">×</button></td></tr>`).join(''):'<tr><td colspan="14" class="ex-empty">Nessuna operazione registrata.</td></tr>'}</tbody></table></div><p class="ex-hint">Ogni operazione va in una sessione (I…X) del suo giorno: il valore della sessione nel Diario diventa la somma delle sue operazioni.</p><input hidden type="file" id="ex-generic-file" accept=".csv,.txt,text/csv,text/plain"></section>`}

function groupStats(ops,by){let weekdays=['domenica','lunedì','martedì','mercoledì','giovedì','venerdì','sabato'],m={};ops.forEach(o=>{let k=by==='weekday'?weekdays[new Date(o.day+'T12:00:00').getDay()]:String(o[by]||'(non indicato)');(m[k]||(m[k]=[])).push(o)});return Object.entries(m).map(([key,a])=>{let profit=round2(a.reduce((s,o)=>s+(Number(o.profit)||0),0)),staked=round2(a.reduce((s,o)=>s+(Number(o.stake)||0),0));return {key,n:a.length,wins:a.filter(o=>Number(o.profit)>0).length,profit,avg:a.length?profit/a.length:0,roi:staked?profit/staked*100:null,best:Math.max(...a.map(o=>Number(o.profit)||0)),worst:Math.min(...a.map(o=>Number(o.profit)||0))}}).sort((a,b)=>b.profit-a.profit)}
function lineSvg(values,cls='bank'){if(values.length<2)return '<div class="ex-chart-empty">Nessun dato</div>';let W=900,H=210,p=18,min=Math.min(...values),max=Math.max(...values);if(min===max)max=min+1;let pts=values.map((v,i)=>`${i?'L':'M'} ${(p+(W-p*2)*i/(values.length-1)).toFixed(1)} ${(p+(H-p*2)*(1-(v-min)/(max-min))).toFixed(1)}`).join(' ');return `<svg class="ex-linechart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="18" x2="882" y1="18" y2="18"/><line x1="18" x2="882" y1="105" y2="105"/><line x1="18" x2="882" y1="192" y2="192"/><path class="${cls}" d="${pts}"/></svg>`}
function statsHtml(p){let allops=state.statsScope==='all'?state.periods.flatMap(x=>x.ops):p.ops,gs=groupStats(allops,state.statsBy),acc=0,curve=[0];[...allops].sort((a,b)=>(a.day+a.slot).localeCompare(b.day+b.slot)).forEach(o=>{acc+=Number(o.profit)||0;curve.push(round2(acc))});let best=gs[0],worst=gs[gs.length-1];return `<section class="ex-tab-pane"><div class="ex-stats-toolbar"><label>Raggruppa per <select id="ex-stats-by"><option value="strategy">strategia</option><option value="market">mercato</option><option value="side">punta / banca</option><option value="league">campionato</option><option value="weekday">giorno della settimana</option><option value="event">partita</option></select></label><label>Ambito <select id="ex-stats-scope"><option value="period">questo periodo</option><option value="all">tutti i periodi</option></select></label></div><div class="ex-table-wrap"><table class="ex-table"><thead><tr><th>VOCE</th><th>OPERAZIONI</th><th>% POSITIVE</th><th>PROFITTO</th><th>MEDIA</th><th>ROI STAKE</th><th>MIGLIORE</th><th>PEGGIORE</th></tr></thead><tbody>${gs.length?gs.map(g=>`<tr><td><b>${esc(g.key)}</b></td><td>${g.n}</td><td>${Math.round(g.wins/g.n*100)}%</td><td class="${g.profit>0?'pos':g.profit<0?'neg':''}">${money(g.profit,true)}</td><td>${money(g.avg,true)}</td><td>${g.roi==null?'':pct(g.roi,1)}</td><td class="pos">${money(g.best,true)}</td><td class="neg">${money(g.worst,true)}</td></tr>`).join(''):'<tr><td colspan="8" class="ex-empty">Registra delle operazioni per vedere le statistiche.</td></tr>'}</tbody></table></div><div class="ex-chart-card"><b>PROFITTO CUMULATO · operazione per operazione</b>${lineSvg(curve,acc>=0?'bank':'drawdown')}</div>${gs.length?`<div class="ex-reading"><b>Lettura</b><br>${allops.length} operazioni, totale ${money(acc,true)}. Rende di più <b>${esc(best.key)}</b> (${money(best.profit,true)} su ${best.n})${worst!==best&&worst.profit<0?`; perde di più <b>${esc(worst.key)}</b> (${money(worst.profit,true)} su ${worst.n})`:''}.${allops.length<50?'<br><span>Con meno di 50 operazioni i risultati per gruppo dipendono molto dal caso: continua a registrare prima di cambiare strategia.</span>':''}</div>`:''}</section>`}
function calendarHtml(p){let vals={};rows(p).forEach(r=>{if(r.sessions)vals[r.day]=r.profit});let months=[];for(let i=0;i<p.length;i++){let d=addDays(p.start,i),k=d.slice(0,7);if(!months.includes(k))months.push(k)}months=months.slice(0,3);let mx=Math.max(1,...Object.values(vals).map(Math.abs));return `<div class="ex-calendar">${months.map(k=>{let [y,m]=k.split('-').map(Number),first=new Date(y,m-1,1),last=new Date(y,m,0).getDate(),offset=(first.getDay()+6)%7,cells=[];for(let i=0;i<offset;i++)cells.push('<i></i>');for(let d=1;d<=last;d++){let iso=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,v=vals[iso],a=v==null?0:Math.min(1,Math.abs(v)/mx);cells.push(`<i class="${v>0?'good':v<0?'bad':''} ${iso===todayIso()?'today':''}" style="--a:${a}">${d}</i>`)}return `<div class="ex-month"><b>${new Date(y,m-1,1).toLocaleDateString('it-IT',{month:'long',year:'numeric'})}</b><div class="week"><span>L</span><span>M</span><span>M</span><span>G</span><span>V</span><span>S</span><span>D</span></div><div class="days">${cells.join('')}</div></div>`}).join('')}</div>`}
function chartHtml(p){let s=summary(p),rs=rows(p),last=Math.max(-1,...rs.map((r,i)=>r.sessions||r.deposit?i:-1)),bank=[p.cash],target=[p.cash],dd=[0];if(last>=0)rs.slice(0,last+1).forEach(r=>{bank.push(r.bank);target.push(r.target);dd.push(r.drawdown)});let combined=[...bank,...target],W=900,H=220,pad=18,min=Math.min(...combined),max=Math.max(...combined);if(min===max)max=min+1;function path(vals){return vals.map((v,i)=>`${i?'L':'M'} ${(pad+(W-pad*2)*i/(vals.length-1||1)).toFixed(1)} ${(pad+(H-pad*2)*(1-(v-min)/(max-min))).toFixed(1)}`).join(' ')}return `<section class="ex-tab-pane"><div class="ex-summary-tiles">${[['Giornate positive',s.positive,'pos'],['Giornate negative',s.negative,'neg'],['Giornata migliore',money(s.best,true),'pos'],['Giornata peggiore',money(s.worst,true),'neg'],['Rendimento del periodo',pct(s.profitPct,2),s.profit>=0?'pos':'neg'],['Sessioni di trading',s.sessions,''],['Depositi e prelievi',money(s.deposits,true),''],['Cassa target a fine periodo',money(s.targetFinal),''],['A questo ritmo a fine periodo',s.projection==null?'—':money(s.projection),''],['Calo massimo della cassa',money(s.maxDrawdown),'neg']].map(x=>`<div><small>${x[0]}</small><b class="${x[2]}">${x[1]}</b></div>`).join('')}</div><div class="ex-chart-card"><b>CASSA REALE E CASSA TARGET · giorno per giorno</b>${bank.length>1?`<svg class="ex-linechart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="18" x2="882" y1="18" y2="18"/><line x1="18" x2="882" y1="110" y2="110"/><line x1="18" x2="882" y1="202" y2="202"/><path class="target" d="${path(target)}"/><path class="bank" d="${path(bank)}"/></svg><div class="ex-legend"><span>● Cassa reale</span><span>--- Cassa target</span></div>`:'<div class="ex-chart-empty">Il grafico compare dopo i primi giorni registrati</div>'}</div><div class="ex-chart-split"><div class="ex-chart-card"><b>CALENDARIO · verde giornate positive, rosso negative</b>${calendarHtml(p)}</div><div class="ex-chart-card"><b>CALO DAL MASSIMO DELLA CASSA · giorno per giorno</b>${lineSvg(dd,'drawdown')}</div></div><div class="ex-reading"><b>Lettura del periodo</b><br>Cassa attuale ${money(s.bank)}, profitto ${money(s.profit,true)}, ${s.reached} giornate a target su ${s.traded} giornate con trading. Drawdown massimo ${money(s.maxDrawdown)}.</div></section>`}
function calcNet(x,c){return x>0?x*(1-c/100):x}
function calcHtml(p){return `<section class="ex-tab-pane"><div class="ex-commission"><label>Commissione exchange <input id="ex-commission" type="number" step="0.5" min="0" max="20" value="${p.commission}"> %</label></div><div class="ex-calc-grid"><article><b>PUNTA E POI BANCA (chiusura)</b>${field('Stake punta','ex-c1-stake',10,'number','step="0.01"')}${field('Quota punta','ex-c1-in',3,'number','step="0.01"')}${field('Quota banca ora','ex-c1-out',2.5,'number','step="0.01"')}${button('CALCOLA','calc-back-lay','primary')}<div id="ex-c1-result" class="ex-calc-result"></div></article><article><b>BANCA E POI PUNTA (chiusura)</b>${field('Stake banca','ex-c2-stake',10,'number','step="0.01"')}${field('Quota banca','ex-c2-in',2.5,'number','step="0.01"')}${field('Quota punta ora','ex-c2-out',3,'number','step="0.01"')}${button('CALCOLA','calc-lay-back','primary')}<div id="ex-c2-result" class="ex-calc-result"></div></article><article><b>BANCATA SEMPLICE</b>${field('Stake banca','ex-c3-stake',10,'number','step="0.01"')}${field('Quota banca','ex-c3-odds',3,'number','step="0.01"')}${button('CALCOLA','calc-lay','primary')}<div id="ex-c3-result" class="ex-calc-result"></div></article></div><p class="ex-hint">La chiusura calcola la seconda puntata che rende uguale il risultato su tutti gli esiti (green-up); la commissione si applica solo alla vincita netta.</p></section>`}

function periodModalHtml(p,title){let n=p||{name:new Date().toLocaleDateString('it-IT',{month:'long',year:'numeric'}),start:todayIso(),cash:100,targetPct:5,stakePct:3,length:31,targetMode:'bank',commission:5,rules:{stopLossPct:5,stopWin:true,maxSessions:0,maxStakePct:0}};return `<div class="ex-overlay"><div class="ex-modal period"><div class="ex-modal-head"><div><span>CONFIGURAZIONE</span><h2>${esc(title||'Nuovo periodo')}</h2></div><button data-ex-action="close-modal">×</button></div><div class="ex-period-form">${field('Nome','ex-p-name',n.name)}${field('Primo giorno','ex-p-start',n.start,'date')}${field('Cassa iniziale','ex-p-cash',n.cash,'number','step="0.01" min="1"')}${field('Take profit giornaliero','ex-p-target',n.targetPct,'number','step="0.5" min="0" max="100"')}${field('Stop loss giornaliero','ex-p-stoploss',n.rules.stopLossPct,'number','step="0.5" min="0" max="100"')}${field('Importo da usare','ex-p-stake',n.stakePct,'number','step="0.5" min="0.1" max="100"')}${field('Durata','ex-p-length',n.length,'number','min="1" max="366"')}${selectField('Target','ex-p-mode',TARGET_MODES,n.targetMode)}</div><div class="ex-rules-title">REGOLE DI DISCIPLINA</div><div class="ex-period-form rules"><label class="ex-check"><input id="ex-p-stopwin" type="checkbox" ${n.rules.stopWin?'checked':''}> Avvisami quando raggiungo il target del giorno</label>${field('Sessioni massime al giorno','ex-p-maxsessions',n.rules.maxSessions,'number','min="0" max="10"')}${field('Stake massimo per operazione','ex-p-maxstake',n.rules.maxStakePct,'number','step="0.5" min="0" max="100"')}</div><div id="ex-p-info" class="ex-period-info"></div><div class="ex-modal-actions">${button('Annulla','close-modal')}${button('Salva','save-period','primary')}</div></div></div>`}
function importModalHtml(x){let rows=x.rows||[],inside=x.inside||[],newOps=x.newOps||[],sum=x.sum||0;return `<div class="ex-overlay"><div class="ex-modal import"><div class="ex-modal-head"><div><span>IMPORT BETFLAG</span><h2>MovimentiChiusi.csv</h2></div><button data-ex-action="close-import">×</button></div><div class="ex-import-summary"><div><small>Operazioni con profitto</small><b>${rows.length}</b></div><div><small>Totale file</small><b class="${sum>=0?'pos':'neg'}">${money(sum,true)}</b></div><div><small>NaN ignorate</small><b>${x.noProfit||0}</b></div><div><small>Nuove nel periodo</small><b>${newOps.length}</b></div></div><p>Nel file: <b>${rows.length}</b> operazioni dal ${x.first?dateShort(x.first):'—'} al ${x.last?dateFull(x.last):'—'}, totale <b>${money(sum,true)}</b>.</p>${x.noProfit?`<p>${x.noProfit} righe senza profitto (NaN: non abbinate o annullate) vengono ignorate.</p>`:''}${rows.length-inside.length?`<p>${rows.length-inside.length} operazioni sono fuori dal periodo «${esc(current()?.name||'')}» e non verranno importate.</p>`:''}${inside.length-newOps.length?`<p>${inside.length-newOps.length} erano già state importate e vengono saltate.</p>`:''}${newOps.length?`<label class="ex-field ex-import-system"><span>Sistema da assegnare a queste operazioni</span><select id="ex-import-system"><option value="">Nessuno · operazioni fuori dai filtri</option><option value="auto">Dal mercato (1X2 → LAY X HT · 1° tempo 0.5 → O0.5 HT · 1.5 → O1.5 25-70)</option>${SYSTEMS.map(z=>`<option value="${esc(z.name)}">Tutte a ${esc(z.name)}</option>`).join('')}</select></label>`:''}<p><b>${newOps.length?`Importo ${newOps.length} operazioni (${money(newOps.reduce((a,z)=>a+z.data.profit,0),true)})?`:'Niente di nuovo da importare.'}</b><br>Le operazioni sulla stessa partita nello stesso giorno vanno nella stessa sessione.</p><div class="ex-modal-actions">${button('Annulla','close-import')}${newOps.length?button('IMPORTA','confirm-betflag','primary'):''}</div></div></div>`}
function genericModalHtml(){return `<div class="ex-overlay"><div class="ex-modal generic"><div class="ex-modal-head"><div><span>IMPORT</span><h2>Altra tabella / CSV</h2></div><button data-ex-action="close-generic">×</button></div><p>Carica un CSV o incolla una tabella con una operazione per riga. Servono almeno Data e Profitto.</p><div class="ex-generic-actions"><label class="ex-file-btn primary">Apri file CSV…<input hidden type="file" id="ex-generic-modal-file" accept=".csv,.txt"></label></div><textarea id="ex-generic-text" placeholder="…oppure incolla qui il testo"></textarea><div id="ex-generic-preview" class="ex-generic-preview">In attesa dei dati…</div><div class="ex-modal-actions">${button('Annulla','close-generic')}${button('Importa','confirm-generic','primary')}</div></div></div>`}
function emptyMain(){return `<div class="ex-main-empty"><div class="ex-xbadge">X</div><h2>Inizia dal CSV Betflag</h2><p>Puoi caricare subito <b>MovimentiChiusi.csv</b>. EasyBet leggerà le date del file e ti preparerà automaticamente il primo periodo; dovrai solo confermare la cassa iniziale e le impostazioni.</p><div class="ex-empty-actions">${button('⬆ IMPORTA CSV BETFLAG','betflag-import','primary')}${button('+ CREA PERIODO MANUALMENTE','new-period')}</div><small>Il CSV non viene importato finché non confermi il periodo.</small></div>`}
function wilson(w,n){if(!n)return [0,0];let z=1.96,ph=w/n,d=1+z*z/n,c=ph+z*z/(2*n),m=z*Math.sqrt(ph*(1-ph)/n+z*z/(4*n*n));return [Math.max(0,(c-m)/d*100),Math.min(100,(c+m)/d*100)]}
function systemStats(sys){let ops=state.periods.flatMap(x=>x.ops||[]).filter(o=>o.strategy===sys.name),dec=ops.filter(o=>Number(o.profit)!==0),win=dec.filter(o=>Number(o.profit)>0),los=dec.filter(o=>Number(o.profit)<0),n=dec.length,wp=n?win.length/n*100:0,aw=win.length?win.reduce((a,o)=>a+Number(o.profit),0)/win.length:0,al=los.length?Math.abs(los.reduce((a,o)=>a+Number(o.profit),0))/los.length:0,be=aw>0&&al>0?al/(aw+al)*100:null,profit=round2(ops.reduce((a,o)=>a+(Number(o.profit)||0),0)),withOdds=ops.filter(o=>Number(o.oddsIn)>0),viol=withOdds.filter(o=>oddsOutsideRule(sys,o.oddsIn)).length,avgOdds=withOdds.length?withOdds.reduce((a,o)=>a+Number(o.oddsIn),0)/withOdds.length:0,ci=wilson(win.length,n),delta=wp-sys.target,light=!n?'none':delta>=-1?'green':delta>-3?'yellow':'red';return {ops,n,total:ops.length,zero:ops.length-n,wins:win.length,losses:los.length,wp,aw,al,be,profit,viol,withOdds:withOdds.length,avgOdds,ci,delta,light}}
function systemVerdict(sys,st){if(!st.n)return 'Nessuna operazione registrata con questo sistema.';let small=st.n<SYSTEM_VERIFY,inCi=sys.target>=st.ci[0]&&sys.target<=st.ci[1];if(small){return `Mancano <b>${SYSTEM_VERIFY-st.n}</b> operazioni per completare la verifica. ${inCi?'Per ora il risultato è compatibile con il backtest.':st.delta<0?'Per ora sei sotto il backtest in modo marcato: controlla la disciplina sulle quote.':'Per ora sei sopra il backtest.'}`}if(st.light==='green')return '<b>Verifica superata:</b> il sistema conferma il backtest. Puoi passare all’1% della cassa.';if(st.light==='yellow')return '<b>Verifica incerta:</b> sei un po’ sotto il backtest. Continua a puntata minima per altre 50 operazioni.';return '<b>Verifica non superata:</b> sei 3 o più punti sotto il backtest. Metti il sistema in pausa e rivedilo.'}
function systemsHtml(p){let all=state.periods.flatMap(x=>x.ops||[]),free=all.filter(o=>!String(o.strategy||'').trim()),auto=free.filter(o=>systemForMarket(o.market)).length;let lab={green:'IN LINEA',yellow:'ATTENZIONE',red:'SOTTO OBIETTIVO',none:'NESSUN DATO'};let cards=SYSTEMS.map(sys=>{let st=systemStats(sys),prog=Math.min(100,st.n/SYSTEM_VERIFY*100);return `<article class="ex-sys-card ${st.light}"><header><div><b>${esc(sys.name)}</b><small>${esc(sys.status)} · backtest ${esc(sys.sample)}</small></div><span class="ex-sys-light ${st.light}">${st.n&&st.n<30?'POCHI DATI · ':''}${lab[st.light]}</span></header><div class="ex-sys-rule">${esc(sys.rule)}</div><div class="ex-sys-kpi"><div><small>% vinte reale</small><b class="${st.n?(st.light==='green'?'pos':st.light==='red'?'neg':''):''}">${st.n?pct(st.wp,1):'—'}</b><span>${st.n?`intervallo 95%: ${pct(st.ci[0],0)} – ${pct(st.ci[1],0)}`:'&nbsp;'}</span></div><div><small>Obiettivo backtest</small><b>${pct(sys.target,1)}</b><span>${st.n?`scarto ${st.delta>=0?'+':''}${st.delta.toLocaleString('it-IT',{maximumFractionDigits:1})} punti`:'&nbsp;'}</span></div><div><small>Pareggio reale</small><b>${st.be==null?'—':pct(st.be,1)}</b><span>${st.be==null?'servono vinte e perse':`vinta media ${money(st.aw,true)} · persa media ${money(-st.al)}`}</span></div><div><small>Profitto</small><b class="${st.profit>0?'pos':st.profit<0?'neg':''}">${money(st.profit,true)}</b><span>${st.wins} vinte · ${st.losses} perse${st.zero?` · ${st.zero} a zero`:''}</span></div></div><div class="ex-sys-progress"><div><span style="width:${prog.toFixed(1)}%"></span></div><small>${st.n} / ${SYSTEM_VERIFY} operazioni per la verifica</small></div><div class="ex-sys-foot">${st.withOdds?`Quota media di entrata <b>${st.avgOdds.toFixed(2)}</b> · ${st.viol?`<em class="neg">${st.viol} entrate fuori regola</em>`:'<em class="pos">tutte le entrate rispettano la regola</em>'}`:'Scrivi la <b>quota di entrata</b> nelle operazioni per controllare la regola.'}</div><div class="ex-sys-verdict">${systemVerdict(sys,st)}</div></article>`}).join('');return `<section class="ex-tab-pane"><div class="ex-reading"><b>Verifica sistemi · tutti i periodi</b><br>Ogni operazione con un sistema come <b>strategia</b> viene confrontata con il backtest. Verde: in linea (fino a −1 punto). Giallo: da −1 a −3 punti. Rosso: 3 o più punti sotto. Le operazioni a profitto zero non entrano nella percentuale.<div class="ex-sys-assign"><span>Contano solo le operazioni in cui hai scelto il sistema come <b>strategia</b>: in Operazioni, oppure all'import Betflag con «Sistema da assegnare». Le giocate fuori dai filtri restano fuori dalla verifica.</span></div></div><div class="ex-sys-grid">${cards}</div></section>`}
function mainHtml(p){return `<div class="ex-app-shell">${sidebarHtml(p)}<main class="ex-content">${p?headerHtml(p)+tabsHtml()+(state.tab==='diary'?diaryHtml(p):state.tab==='ops'?opsHtml(p):state.tab==='stats'?statsHtml(p):state.tab==='chart'?chartHtml(p):state.tab==='systems'?systemsHtml(p):calcHtml(p)):emptyMain()}</main></div>${state.editor?periodModalHtml(state.editor==='new'?null:p,state.editor==='edit'?'Modifica periodo':state.editor==='next'?'Periodo successivo':'Nuovo periodo'):''}${state.importPreview?importModalHtml(state.importPreview):''}${state.importGeneric?genericModalHtml():''}`}
function render(force){let r=root();if(!r)return;r.classList.add('show');if(!force&&r.dataset.exRendered==='1'){let a=document.activeElement,editing=!!(state.editor||state.importPreview||state.importGeneric),typing=!!(a&&r.contains(a)&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName));if(editing||typing)return;}r.dataset.exRendered='1';if(!state.loaded&&!state.loading){r.innerHTML='<div class="ex-loading">Caricamento Diario Exchange…</div>';load();return}if(state.loading){r.innerHTML='<div class="ex-loading">Caricamento Diario Exchange…</div>';return}if(state.locked){r.innerHTML=lockedHtml();return}let p=current();r.innerHTML=mainHtml(p);if(state.tab==='stats'){let a=document.getElementById('ex-stats-by'),b=document.getElementById('ex-stats-scope');if(a)a.value=state.statsBy;if(b)b.value=state.statsScope}if(state.editor)updatePeriodInfo();if(state.importGeneric&&state.importGeneric.text){let t=document.getElementById('ex-generic-text');if(t){t.value=state.importGeneric.text;updateGenericPreview()}}}

function readPeriodForm(base){let sameStop=document.getElementById('ex-p-stoploss');let n=normalizePeriod({uid:base?.uid||'',name:document.getElementById('ex-p-name').value,start:document.getElementById('ex-p-start').value,cash:parseAmount(document.getElementById('ex-p-cash').value)||100,targetPct:parseAmount(document.getElementById('ex-p-target').value)||0,stakePct:parseAmount(document.getElementById('ex-p-stake').value)||3,length:Number(document.getElementById('ex-p-length').value)||31,targetMode:document.getElementById('ex-p-mode').value,commission:base?.commission??5,rules:{stopLossPct:parseAmount(sameStop.value)||0,stopWin:document.getElementById('ex-p-stopwin').checked,maxSessions:Number(document.getElementById('ex-p-maxsessions').value)||0,maxStakePct:parseAmount(document.getElementById('ex-p-maxstake').value)||0},days:base?.days||{},ops:base?.ops||[]});return n}
function updatePeriodInfo(){let c=parseAmount(document.getElementById('ex-p-cash')?.value)||0,tp=parseAmount(document.getElementById('ex-p-target')?.value)||0,sl=parseAmount(document.getElementById('ex-p-stoploss')?.value)||0,len=Number(document.getElementById('ex-p-length')?.value)||31,mode=document.getElementById('ex-p-mode')?.value||'bank',mult=mode==='linear'?1+tp/100*len:Math.pow(1+tp/100,len),info=document.getElementById('ex-p-info');if(!info)return;info.textContent=mode==='bank'?`Ogni giorno: take profit +${tp.toFixed(2)}% e stop loss -${sl.toFixed(2)}% sulla stessa base. Se raggiungessi il take profit tutti i giorni, a fine periodo la cassa sarebbe ${money(c*mult)} (×${mult.toFixed(2)}).`:`Cassa target a fine periodo: ${money(c*mult)} (×${mult.toFixed(2)}).`}
async function createOrUpdatePeriod(){let p=current(),base=state.editor==='edit'?p:null;if(state.editor==='next'&&p){base=normalizePeriod({...p,uid:'',name:'',start:addDays(p.start,p.length),cash:summary(p).bank,days:{},ops:[]})}let n=readPeriodForm(base),saved=null;if(base?.uid){let j=await api('/api/exchange/periods/'+encodeURIComponent(base.uid),{method:'PUT',body:JSON.stringify(n)}),x=normalizePeriod(j.period),i=state.periods.findIndex(z=>z.uid===x.uid);if(i>=0)state.periods[i]=x;state.currentUid=x.uid;saved=x}else{let j=await api('/api/exchange/periods',{method:'POST',body:JSON.stringify(n)}),x=normalizePeriod(j.period);state.periods.unshift(x);state.currentUid=x.uid;saved=x}state.editor=null;state.notice='● salvataggio automatico attivo';if(state.pendingBetflagText&&saved){try{state.importPreview=previewBetflag(state.pendingBetflagText,saved);state.pendingBetflagText='';state.pendingBetflagMeta=null;state.notice='CSV Betflag letto: controlla l’anteprima e conferma l’importazione.'}catch(err){state.pendingBetflagText='';state.pendingBetflagMeta=null;state.notice=err.message||'Errore lettura CSV'}}render(true)}

function quickAdd(p){let day=document.getElementById('ex-q-date').value,val=parseAmount(document.getElementById('ex-q-amount').value),msg=document.getElementById('ex-q-msg');if(!contains(p,day)){msg.textContent='Giorno fuori dal periodo';return}if(val==null){msg.textContent='Scrivi un importo valido';return}let slot=freeSlot(p,day);if(slot==null){msg.textContent='Le 10 sessioni del giorno sono occupate';return}let d=getDay(p,day);while(d.sessions.length<=slot)d.sessions.push(null);d.sessions[slot]=round2(val);setDay(p,day,d);state.notice=`Sessione ${ROMAN[slot]} del ${dateShort(day)}: ${money(val,true)}`;persist(p,true);render(true)}
function calcTradeProfit(side,stake,oi,oo,c=5){if(Math.min(stake,oi-1,oo-1)<=0)return null;let gross=side!=='Banca'?stake*(oi/oo-1):stake*(1-oi/oo);return round2(calcNet(gross,c))}
function saveOp(p){let day=document.getElementById('ex-op-day').value,profit=parseAmount(document.getElementById('ex-op-profit').value);if(profit==null){alert('Scrivi il profitto netto oppure usa «Calcola profitto dalle quote».');return}if(!contains(p,day)){alert('Il giorno è fuori dal periodo selezionato.');return}let old=state.opEditUid?p.ops.find(o=>o.uid===state.opEditUid):null,slot=Number(document.getElementById('ex-op-slot').value);if(slot<0){slot=old?Number(old.slot):freeSlot(p,day);if(slot==null){alert('Le 10 sessioni del giorno sono occupate: scegli una sessione in cui aggiungere l’operazione.');return}}let op={uid:old?.uid||uid(),day,slot,event:document.getElementById('ex-op-event').value.trim(),league:old?.league||'',market:document.getElementById('ex-op-market').value.trim(),strategy:document.getElementById('ex-op-strategy').value.trim(),side:document.getElementById('ex-op-side').value,oddsIn:parseAmount(document.getElementById('ex-op-odds-in').value)||0,oddsOut:parseAmount(document.getElementById('ex-op-odds-out').value)||0,stake:Math.abs(parseAmount(document.getElementById('ex-op-stake').value)||0),minute:document.getElementById('ex-op-minute').value.trim(),profit:round2(profit),note:document.getElementById('ex-op-note').value.trim(),ref:old?.ref||''};{let sy=systemByName(op.strategy);if(sy&&oddsOutsideRule(sy,op.oddsIn)&&!confirm(`Quota di entrata ${op.oddsIn} fuori dalla regola di «${sy.name}» (${sy.min?'minimo '+sy.min.toFixed(2):'massimo '+sy.max.toFixed(2)}). Registrare comunque?`))return}if(p.rules.maxStakePct){let rr=rows(p).find(r=>r.day===day),limit=(rr?.startBank||p.cash)*p.rules.maxStakePct/100;if(op.stake>limit&&!confirm(`Lo stake supera il massimo impostato (${money(limit)}). Registrare comunque?`))return}if(old){let oldDay=old.day,oldSlot=Number(old.slot);p.ops[p.ops.indexOf(old)]=op;syncSlot(p,oldDay,oldSlot)}else p.ops.push(op);syncSlot(p,day,slot);state.opEditUid='';persist(p,true);render(true)}

function splitTable(text){let lines=String(text||'').replace(/\r/g,'').split('\n').filter(x=>x.trim());if(!lines.length)return[];let sample=lines.slice(0,30).join('\n'),delim=sample.includes('\t')?'\t':(sample.match(/;/g)||[]).length>=Math.min(30,lines.length)?';':',';function split(line){let out=[],cur='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===delim&&!q){out.push(cur.trim());cur=''}else cur+=c}out.push(cur.trim());return out}let rows=lines.map(split),w=Math.max(...rows.map(r=>r.length));return rows.map(r=>r.concat(Array(w-r.length).fill('')))}
function betflagMarket(m){let t=String(m||'').trim().replace(/\s+/g,' '),low=t.toLowerCase(),maps=[['under and over','Over/Under'],['u/o tempo 1','Over/Under 1° tempo'],['esito finale 1x2','Match Odds']];for(let [k,v] of maps)if(low.startsWith(k)){let rest=t.slice(k.length).replace(/^\s*-\s*/,'').trim();return (v+' '+rest).trim()}return t}
function parseBetflag(text){let rs=splitTable(text);if(!rs.length)throw new Error('File vuoto');let required=['Avvenimento','Manifestazione','Descrizione','Data','Mercato','Profitto'];if(!required.every(c=>rs[0].includes(c)))throw new Error('Il file non sembra un’esportazione «Movimenti chiusi» di Betflag');let h={};rs[0].forEach((x,i)=>h[x]=i);let ops=[],noProfit=0,errors=[];for(let n=1;n<rs.length;n++){let r=rs[n],get=k=>String(r[h[k]]??'').trim(),day=parseDate(get('Data'));if(!day){errors.push(`riga ${n+1}: data non leggibile`);continue}let profit=parseAmount(get('Profitto'));if(profit==null){noProfit++;continue}let dt=get('Data'),tm=dt.includes('T')?dt.slice(11,16):'',data={event:get('Descrizione'),market:betflagMarket(get('Mercato')),side:'Trading',oddsIn:0,oddsOut:0,stake:0,profit:round2(profit),league:get('Manifestazione'),note:tm?'ore '+tm:'',strategy:'',minute:'',ref:'betflag:'+['Palinsesto','Avvenimento','Mercato','Data'].map(get).join('|')};ops.push({day,data})}return {ops,noProfit,errors}}
function previewBetflag(text,p){let r=parseBetflag(text),inside=r.ops.filter(x=>contains(p,x.day)),known=new Set(p.ops.map(o=>o.ref).filter(Boolean)),newOps=inside.filter(x=>!known.has(x.data.ref)),days=r.ops.map(x=>x.day).sort();return {rows:r.ops,noProfit:r.noProfit,errors:r.errors,inside,newOps,sum:round2(r.ops.reduce((a,x)=>a+x.data.profit,0)),first:days[0]||null,last:days[days.length-1]||null}}
function prepareFirstPeriodFromBetflag(text){let r=parseBetflag(text);if(!r.ops.length)throw new Error('Nel file non ci sono operazioni con un profitto.');let days=r.ops.map(x=>x.day).sort(),first=days[0],last=days[days.length-1],[y,m]=first.split('-').map(Number),name=new Date(y,m-1,1).toLocaleDateString('it-IT',{month:'long',year:'numeric'}),d0=new Date(first+'T12:00:00'),d1=new Date(last+'T12:00:00'),length=Math.max(1,Math.round((d1-d0)/86400000)+1);state.pendingBetflagText=String(text||'');state.pendingBetflagMeta={first,last,length,count:r.ops.length,sum:round2(r.ops.reduce((a,x)=>a+x.data.profit,0))};state.editor='new';render(true);setTimeout(()=>{let set=(id,v)=>{let el=document.getElementById(id);if(el)el.value=v};set('ex-p-name',name);set('ex-p-start',first);set('ex-p-length',length);let info=document.getElementById('ex-p-info');if(info)info.innerHTML=`<b>CSV Betflag pronto:</b> ${r.ops.length} operazioni dal ${dateShort(first)} al ${dateFull(last)} · totale ${money(state.pendingBetflagMeta.sum,true)}.<br>Conferma la <b>cassa iniziale</b> e salva: subito dopo vedrai l’anteprima delle operazioni da importare.`;updatePeriodInfo()},0)}
function addBetflag(p,preview){let known=new Set(p.ops.map(o=>o.ref).filter(Boolean)),slotOf={};p.ops.forEach(o=>{if(o.event?.trim())slotOf[o.day+'|'+o.event.trim().toLowerCase()]=Number(o.slot)||0});let added=0;preview.rows.forEach(x=>{if(!contains(p,x.day)||known.has(x.data.ref))return;let twin=p.ops.find(o=>!o.ref&&o.day===x.day&&String(o.event).trim().toLowerCase()===x.data.event.trim().toLowerCase()&&String(o.market).trim().toLowerCase()===x.data.market.trim().toLowerCase()&&Math.abs(Number(o.profit)-x.data.profit)<.005);if(twin){twin.ref=x.data.ref;if(!twin.league)twin.league=x.data.league;known.add(x.data.ref);return}known.add(x.data.ref);let mode=preview.systemMode||'',sn=mode==='auto'?systemForMarket(x.data.market):mode,sy=systemByName(sn);if(sy){x.data.strategy=sy.name;x.data.side=sy.side}let key=x.day+'|'+x.data.event.trim().toLowerCase(),slot=slotOf[key];if(slot==null){slot=freeSlot(p,x.day);if(slot==null)slot=9;slotOf[key]=slot}p.ops.push({uid:uid(),day:x.day,slot,...x.data});syncSlot(p,x.day,slot);added++});return added}
function genericParse(text,p){let rs=splitTable(text);if(!rs.length)return {ops:[],errors:['nessun dato']};let header=rs[0].map(x=>x.toLowerCase()),idx={};function find(k,arr){for(let i=0;i<header.length;i++)if(arr.some(a=>header[i].includes(a))){idx[k]=i;return}}find('date',['data','date','giorno','piazzata','regolata','settled','placed']);find('event',['evento','event','partita','incontro','descrizione','match']);find('market',['mercato','market','scommessa']);find('side',['tipo','lato','side','punta','banca','back','lay','bet type']);find('odds',['quota','odds','price','prezzo']);find('stake',['stake','importo','puntata','giocata','size']);find('profit',['profitto','p&l','p/l','utile','risultato','vincita','netto','profit','guadagno','saldo']);if(idx.date==null||idx.profit==null)return {ops:[],errors:['Mancano almeno Data e Profitto']};let out=[],errors=[];rs.slice(1).forEach((r,n)=>{let get=k=>idx[k]!=null?String(r[idx[k]]||'').trim():'',day=parseDate(get('date')),profit=parseAmount(get('profit'));if(!day||profit==null){if(r.some(Boolean))errors.push('riga '+(n+2));return}let side=get('side');side=/banc|lay/i.test(side)?'Banca':/punt|back/i.test(side)?'Punta':'Trading';out.push({day,data:{event:get('event'),market:get('market'),side,oddsIn:parseAmount(get('odds'))||0,oddsOut:0,stake:Math.abs(parseAmount(get('stake'))||0),profit:round2(profit),league:'',note:'',strategy:'',minute:'',ref:''}})});return {ops:out,errors}}
function addGeneric(p,result){let slotOf={},added=0,skipped=0;result.ops.forEach(x=>{if(!contains(p,x.day)){skipped++;return}let key=x.day+'|'+x.data.event.trim().toLowerCase(),slot=slotOf[key];if(slot==null){slot=freeSlot(p,x.day);if(slot==null)slot=9;slotOf[key]=slot}p.ops.push({uid:uid(),day:x.day,slot,...x.data});syncSlot(p,x.day,slot);added++});return {added,skipped}}
function updateGenericPreview(){let t=document.getElementById('ex-generic-text'),v=document.getElementById('ex-generic-preview'),p=current();if(!t||!v||!p)return;state.importGeneric={text:t.value};let r=genericParse(t.value,p),tot=r.ops.reduce((a,x)=>a+x.data.profit,0);v.innerHTML=r.ops.length?`<b>${r.ops.length} operazioni leggibili</b>, totale ${money(tot,true)}${r.errors.length?' · '+r.errors.length+' righe non leggibili':''}`:`<span>${esc(r.errors[0]||'Nessuna operazione leggibile')}</span>`}

function calcBackLay(p){let stake=parseAmount(document.getElementById('ex-c1-stake').value)||0,bi=parseAmount(document.getElementById('ex-c1-in').value)||0,lo=parseAmount(document.getElementById('ex-c1-out').value)||0,r=document.getElementById('ex-c1-result');if(Math.min(stake,bi-1,lo-1)<=0){r.textContent='Valori non validi';return}let ls=stake*bi/lo,win=stake*(bi-1)-ls*(lo-1),lose=-stake+ls;r.innerHTML=`<b>Stake Lay ${money(ls)}</b><span>Responsabilità ${money(ls*(lo-1))}<br>Profitto ${money(calcNet(win,p.commission),true)} / ${money(calcNet(lose,p.commission),true)}</span>`}
function calcLayBack(p){let stake=parseAmount(document.getElementById('ex-c2-stake').value)||0,li=parseAmount(document.getElementById('ex-c2-in').value)||0,bo=parseAmount(document.getElementById('ex-c2-out').value)||0,r=document.getElementById('ex-c2-result');if(Math.min(stake,li-1,bo-1)<=0){r.textContent='Valori non validi';return}let bs=stake*li/bo,win=-stake*(li-1)+bs*(bo-1),lose=stake-bs;r.innerHTML=`<b>Stake Back ${money(bs)}</b><span>Responsabilità iniziale ${money(stake*(li-1))}<br>Profitto ${money(calcNet(win,p.commission),true)} / ${money(calcNet(lose,p.commission),true)}</span>`}
function calcLay(p){let stake=parseAmount(document.getElementById('ex-c3-stake').value)||0,o=parseAmount(document.getElementById('ex-c3-odds').value)||0,r=document.getElementById('ex-c3-result');if(Math.min(stake,o-1)<=0){r.textContent='Valori non validi';return}r.innerHTML=`<b>Responsabilità ${money(stake*(o-1))}</b><span>Vincita netta ${money(calcNet(stake,p.commission),true)}</span>`}
function csvSemi(v){let s=String(v==null?'':v);return /[;\n"]/g.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function csvNum(v){return v==null?'':Number(v).toFixed(2).replace('.',',')}
function exportPeriodCsv(p){let head=['Data','Cassa target','Profitto richiesto','Profitto fatto','Cassa','Importo','Rendimento %','Esito','Margine','Sessioni'].concat(Array.from({length:10},(_,i)=>'S'+(i+1))).concat(['Depositi/prelievi','Note']);let lines=[head.map(csvSemi).join(';')];rows(p).forEach(r=>{let d=getDay(p,r.day),vals=[dateFull(r.day),csvNum(r.target),csvNum(r.required),csvNum(r.profit),csvNum(r.bank),csvNum(r.stake),r.ret==null?'':csvNum(r.ret),r.outcome,r.margin==null?'':csvNum(r.margin),r.sessions];for(let i=0;i<10;i++)vals.push(d.sessions[i]==null?'':csvNum(d.sessions[i]));vals.push(d.deposit?csvNum(d.deposit):'',d.note);lines.push(vals.map(csvSemi).join(';'))});download('Diario '+p.name+'.csv','\ufeff'+lines.join('\n'),'text/csv;charset=utf-8')}
function download(name,text,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:type||'application/octet-stream'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backup(){download('DiarioExchange-EasyBet-'+todayIso()+'.json',JSON.stringify({app:'DiarioExchange/1',selected:state.currentUid,commission:current()?.commission||5,theme:document.documentElement.dataset.theme||'dark',periods:state.periods},null,2),'application/json')}
async function restoreBackup(text){let d=JSON.parse(text);if(!d||!Array.isArray(d.periods))throw new Error('Il file non è un backup del Diario Exchange');for(let p of d.periods){p=normalizePeriod(p);let existing=state.periods.find(x=>x.uid===p.uid);if(existing){let j=await api('/api/exchange/periods/'+encodeURIComponent(existing.uid),{method:'PUT',body:JSON.stringify(p)});Object.assign(existing,normalizePeriod(j.period))}else{let j=await api('/api/exchange/periods',{method:'POST',body:JSON.stringify({...p,uid:''})});state.periods.unshift(normalizePeriod(j.period))}}state.currentUid=state.periods[0]?.uid||'';state.notice='Backup ripristinato';render(true)}

function bind(){document.addEventListener('click',async e=>{let rr=e.target.closest('#exchangeBoard');if(!rr)return;let per=e.target.closest('[data-ex-period]');if(per){state.currentUid=per.dataset.exPeriod;state.tab='diary';state.opEditUid='';render(true);return}let tab=e.target.closest('[data-ex-tab]');if(tab){state.tab=tab.dataset.exTab;state.opEditUid='';render(true);return}let b=e.target.closest('[data-ex-action]');if(!b)return;let a=b.dataset.exAction,p=current();try{if(a==='new-period'){state.editor='new';render(true)}else if(a==='next-period'){state.editor='next';render(true);let cp=current();if(cp){setTimeout(()=>{document.getElementById('ex-p-name').value='';document.getElementById('ex-p-start').value=addDays(cp.start,cp.length);document.getElementById('ex-p-cash').value=summary(cp).bank;updatePeriodInfo()},0)}}else if(a==='edit-period'){state.editor='edit';render(true)}else if(a==='close-modal'){state.editor=null;state.pendingBetflagText='';state.pendingBetflagMeta=null;render(true)}else if(a==='save-period'){await createOrUpdatePeriod()}else if(a==='clear-period'){if(p&&confirm(`Cancello tutte le giornate e le operazioni di «${p.name}»? Le impostazioni restano.`)){p.days={};p.ops=[];persist(p,true);render(true)}}else if(a==='delete-period'){if(p&&confirm(`Elimino il periodo «${p.name}» con tutte le sue giornate?`)){await api('/api/exchange/periods/'+encodeURIComponent(p.uid),{method:'DELETE'});state.periods=state.periods.filter(x=>x.uid!==p.uid);state.currentUid=state.periods[0]?.uid||'';render(true)}}else if(a==='quick-add'){quickAdd(p)}else if(a==='save-op'){saveOp(p)}else if(a==='cancel-op'){state.opEditUid='';render(true)}else if(a==='edit-op'){state.opEditUid=b.dataset.op;render(true)}else if(a==='delete-op'){let o=p.ops.find(x=>x.uid===b.dataset.op);if(o&&confirm(`Elimino l'operazione «${o.event||'senza nome'}» (${money(o.profit,true)})?`)){p.ops=p.ops.filter(x=>x.uid!==o.uid);syncSlot(p,o.day,o.slot);persist(p,true);render(true)}}else if(a==='calc-op-profit'){let v=calcTradeProfit(document.getElementById('ex-op-side').value,parseAmount(document.getElementById('ex-op-stake').value)||0,parseAmount(document.getElementById('ex-op-odds-in').value)||0,parseAmount(document.getElementById('ex-op-odds-out').value)||0,p.commission);if(v==null)alert('Servono stake e quote di entrata/uscita maggiori di 1');else document.getElementById('ex-op-profit').value=String(v).replace('.',',')}else if(a==='betflag-import'){let inp=document.getElementById('ex-betflag-file-global');if(inp){inp.value='';inp.click()}}else if(a==='generic-import'){state.importGeneric={text:''};render(true)}else if(a==='close-import'){state.importPreview=null;render(true)}else if(a==='confirm-betflag'){state.importPreview.systemMode=document.getElementById('ex-import-system')?.value||'';let n=addBetflag(p,state.importPreview);state.importPreview=null;state.notice=`Importate ${n} operazioni.`;persist(p,true);render(true)}else if(a==='close-generic'){state.importGeneric=null;render(true)}else if(a==='confirm-generic'){let text=document.getElementById('ex-generic-text').value,r=genericParse(text,p);if(!r.ops.length){alert(r.errors[0]||'Nessuna operazione leggibile');return}let z=addGeneric(p,r);state.importGeneric=null;state.notice=`Importate ${z.added} operazioni${z.skipped?' · '+z.skipped+' fuori periodo':''}.`;persist(p,true);render(true)}else if(a==='export-period'){exportPeriodCsv(p)}else if(a==='backup'){backup()}else if(a==='restore-backup'){document.getElementById('ex-restore-file').click()}else if(a==='print-report'){window.print()}else if(a==='calc-back-lay'){calcBackLay(p)}else if(a==='calc-lay-back'){calcLayBack(p)}else if(a==='calc-lay'){calcLay(p)}}catch(err){state.notice=err.message||'Errore';render(true)}});

document.addEventListener('input',e=>{if(!e.target.closest('#exchangeBoard'))return;if(e.target.id?.startsWith('ex-p-'))updatePeriodInfo();if(e.target.id==='ex-generic-text')updateGenericPreview()});
document.addEventListener('change',e=>{if(!e.target.closest('#exchangeBoard'))return;let p=current();if(e.target.id==='ex-op-filter'){state.opFilter=e.target.value;render(true);return}if(e.target.id==='ex-stats-by'){state.statsBy=e.target.value;render(true);return}if(e.target.id==='ex-stats-scope'){state.statsScope=e.target.value;render(true);return}if(e.target.id==='ex-q-date'){document.getElementById('ex-day-banner').innerHTML=quickBanner(p,e.target.value);return}if(e.target.dataset.exSession){let [day,slot]=e.target.dataset.exSession.split('|'),v=parseAmount(e.target.value),d=getDay(p,day);while(d.sessions.length<=+slot)d.sessions.push(null);d.sessions[+slot]=v==null?null:round2(v);setDay(p,day,d);p.ops=p.ops.filter(o=>!(o.day===day&&Number(o.slot)===+slot));persist(p,true);render(true);return}if(e.target.dataset.exDeposit){let d=getDay(p,e.target.dataset.exDeposit);d.deposit=parseAmount(e.target.value)||0;setDay(p,e.target.dataset.exDeposit,d);persist(p,true);render(true);return}if(e.target.dataset.exNote){let d=getDay(p,e.target.dataset.exNote);d.note=e.target.value;setDay(p,e.target.dataset.exNote,d);persist(p,true);return}if(e.target.id==='ex-commission'){p.commission=Math.max(0,Math.min(20,parseAmount(e.target.value)||0));persist(p,true);return}if((e.target.id==='ex-betflag-file'||e.target.id==='ex-betflag-file-global')&&e.target.files?.[0]){let f=e.target.files[0],rd=new FileReader();rd.onload=()=>{try{if(p){state.importPreview=previewBetflag(rd.result,p);render(true)}else prepareFirstPeriodFromBetflag(rd.result)}catch(err){alert(err.message)}};rd.readAsText(f,'UTF-8');return}if(e.target.id==='ex-generic-modal-file'&&e.target.files?.[0]){let rd=new FileReader();rd.onload=()=>{state.importGeneric={text:String(rd.result||'')};render(true)};rd.readAsText(e.target.files[0],'UTF-8');return}if(e.target.id==='ex-restore-file'&&e.target.files?.[0]){let rd=new FileReader();rd.onload=async()=>{try{await restoreBackup(rd.result)}catch(err){alert(err.message)}};rd.readAsText(e.target.files[0],'UTF-8')}})}
bind();
window.EasyBetExchange={render,reload(){state.loaded=false;state.loading=false;load()},_test:{splitTable,parseBetflag,betflagMarket,parseDate,parseAmount,systemForMarket,systemStats,wilson,SYSTEMS}};
})();
